// CreditsafeGlobalDataReportsFinancialRatios defines model for CreditsafeGlobalDataReportsFinancialRatios.
type CreditsafeGlobalDataReportsFinancialRatios struct {
	// CreditorDays Trade Creditors / Turnover x 365 days. This is a calculation that predicts the average time taken for the company to settle its invoices for goods and services provided by its suppliers.
	CreditorDays *float64 `json:"creditorDays,omitempty"`

	// CurrentDebtRatio Total Current Liabilities / Total Shareholders’ Equity. This measures the amount of short-term debt in relation to the value of shareholders’ funds.
	CurrentDebtRatio *float64 `json:"currentDebtRatio,omitempty"`

	// CurrentRatio Total Current Assets - Receivables Due after 1 year / Total Current Liabilities. This is an indication of a company's ability to meet short-term debt obligations; the higher the ratio, the more liquid the company is.
	CurrentRatio *float64 `json:"currentRatio,omitempty"`

	// DebtorDays Trade Debtors / Turnover x 365 days. This is a calculation that predicts the average time taken for the company to collect its invoices for goods and services provided to its customers.
	DebtorDays *float64 `json:"debtorDays,omitempty"`

	// EquityInPercentage Total Shareholders’ Equity / (Total Current Assets + Tangible Fixed Assets – Total Intangible Assets) x 100. This ratio shows the worth of the company (shareholders’ funds) as a percentage of total current and tangible assets.
	EquityInPercentage *float64 `json:"equityInPercentage,omitempty"`

	// Gearing Bank Overdraft & Loans + Total Long-term Liabilities/Total Shareholders’ Equity x 100. This is the relationship between the size of the company’s debt in proportion to Equity (Shareholders Funds).
	Gearing *float64 `json:"gearing,omitempty"`

	// LiquidityRatioOrAcidTest Total Current Assets - Total Inventories - Receivables Due after 1 year / Total Current Liabilities. This, like the current ratio, measures how quickly a company can meet its short-term debts. However, this ratio excludes stock, as there is no guarantee the value of Stocks can be realised quickly.
	LiquidityRatioOrAcidTest *float64 `json:"liquidityRatioOrAcidTest,omitempty"`

	// PreTaxProfitMargin Pre-tax profits / Turnover x 100. This shows the percentage of Profit in each pound of sales or the equivalent of retailers 'mark-up'.
	PreTaxProfitMargin *float64 `json:"preTaxProfitMargin,omitempty"`

	// ReturnOnCapitalEmployed Pre-Tax Profit / Capital Employed x 100. This ratio measures the profits a business yields in return for the money (Capital) invested.
	ReturnOnCapitalEmployed *float64 `json:"returnOnCapitalEmployed,omitempty"`

	// ReturnOnNetAssetsEmployed Pre-Tax Profits / Net Assets x 100. This shows the ‘return’ in percent on the net assets of the company. The higher the percentage the more profitable the company.
	ReturnOnNetAssetsEmployed *float64 `json:"returnOnNetAssetsEmployed,omitempty"`

	// ReturnOnTotalAssetsEmployed Pre-Tax Profits / Total Assets x 100. This shows the ‘return’ or 'profit' on each pound of Assets used as a percentage.
	ReturnOnTotalAssetsEmployed *float64 `json:"returnOnTotalAssetsEmployed,omitempty"`

	// SalesOrNetWorkingCapital Turnover / (Total Current Assets - Receivables Due after 1 year - Total Current Liabilities). The higher the ratio the higher the volume of Sales made per the companies working capital.
	SalesOrNetWorkingCapital *float64 `json:"salesOrNetWorkingCapital,omitempty"`

	// StockTurnoverRatio Stocks / Turnover x 100. This shows the number of times the trading stock of a company is ‘turned over’ in a trading period. If the ratio is low this indicates that relatively little money is tied up in Stocks.
	StockTurnoverRatio *float64 `json:"stockTurnoverRatio,omitempty"`

	// TotalDebtRatio Total Current Liabilities + Total Long-term liabilities / Total Shareholders’ Equity x 100. This shows the relative indebtedness of a company in relation to the worth of the company.
	TotalDebtRatio *float64 `json:"totalDebtRatio,omitempty"`
}

